function Invoke-WingiDirectInstall {
        param(
            [pscustomobject]$Metadata,
            [bool]$SilentRequested
        )

        $uri = [System.Uri]$Metadata.InstallerUrl
        $extension = [System.IO.Path]::GetExtension($uri.AbsolutePath)
        if (-not $extension) { $extension = '.exe' }

